const { useState } = React;

function App() {
  const [doctor, setDoctor] = useState("");
  const [date, setDate] = useState("");
  const [email, setEmail] = useState("");
  const [timeSlot, setTimeSlot] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Lee"];

  function handleSubmit(e) {
    e.preventDefault();
    setError("");
    setSuccess("");
    if (!date) {
      setError("Please select a date.");
      return;
    }
    setSuccess("Appointment booked.");
  }

  return (
    <main style={{
      fontFamily: 'Arial, sans-serif',
      maxWidth: 400,
      margin: '2rem auto',
      padding: '1rem',
      border: '1px solid #ccc',
      borderRadius: 8,
      backgroundColor: '#fff'
    }}>
      <h2 style={{
        fontWeight: 'normal',
        borderBottom: '1px solid #000',
        paddingBottom: '0.5rem',
        marginBottom: '1rem'
      }}>Book appointment</h2>

      <form onSubmit={handleSubmit}>
        <label htmlFor="doctor" style={{ display: 'block', marginBottom: 8, fontWeight: 'bold' }}>
          Select doctor
        </label>
        <select
          id="doctor"
          value={doctor}
          onChange={e => setDoctor(e.target.value)}
          style={{
            width: '100%',
            padding: '0.5rem',
            marginBottom: '1rem',
            fontSize: '1rem',
            borderRadius: 4,
            border: '1px solid #ccc'
          }}
        >
          <option value="" disabled>Select doctor</option>
          {doctors.map((doc, i) => (
            <option key={i} value={doc}>{doc}</option>
          ))}
        </select>

        <label htmlFor="date" style={{ display: 'block', marginBottom: 8, fontWeight: 'bold' }}>
          Date
        </label>
        <input
          id="date"
          type="date"
          value={date}
          onChange={e => setDate(e.target.value)}
          style={{
            width: '100%',
            padding: '0.5rem',
            marginBottom: '1rem',
            fontSize: '1rem',
            borderRadius: 4,
            border: '1px solid #ccc'
          }}
        />

        <label htmlFor="email" style={{ display: 'block', marginBottom: 8, fontWeight: 'bold' }}>
          Email
        </label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          style={{
            width: '100%',
            padding: '0.5rem',
            marginBottom: '1rem',
            fontSize: '1rem',
            borderRadius: 4,
            border: '1px solid #ccc'
          }}
          placeholder="you@example.com"
        />

        <fieldset style={{ border: 'none', marginBottom: '1rem', padding: 0 }}>
          <legend style={{ fontWeight: 'bold', marginBottom: 8 }}>Time slot</legend>
          <label style={{ marginRight: '1rem' }}>
            <input
              type="radio"
              name="timeSlot"
              value="9:00"
              checked={timeSlot === "9:00"}
              onChange={e => setTimeSlot(e.target.value)}
              style={{ marginRight: 4 }}
            />
            9:00
          </label>
          <label style={{ marginRight: '1rem' }}>
            <input
              type="radio"
              name="timeSlot"
              value="11:00"
              checked={timeSlot === "11:00"}
              onChange={e => setTimeSlot(e.target.value)}
              style={{ marginRight: 4 }}
            />
            11:00
          </label>
          <label>
            <input
              type="radio"
              name="timeSlot"
              value="15:00"
              checked={timeSlot === "15:00"}
              onChange={e => setTimeSlot(e.target.value)}
              style={{ marginRight: 4 }}
            />
            15:00
          </label>
        </fieldset>

        <label htmlFor="reason" style={{ display: 'block', marginBottom: 8, fontWeight: 'bold' }}>
          Reason for visit
        </label>
        <textarea
          id="reason"
          value={reason}
          onChange={e => setReason(e.target.value)}
          rows={4}
          style={{
            width: '100%',
            padding: '0.5rem',
            fontSize: '1rem',
            borderRadius: 4,
            border: '1px solid #ccc',
            resize: 'vertical',
            marginBottom: '1rem'
          }}
          placeholder="Reason for visit"
        />

        <button
          type="submit"
          style={{
            width: '100%',
            padding: '0.75rem',
            fontSize: '1rem',
            borderRadius: 4,
            border: 'none',
            backgroundColor: '#007bff',
            color: '#fff',
            cursor: 'pointer'
          }}
        >
          Confirm booking
        </button>

        {error && <p role="alert" style={{ color: 'red', marginTop: '1rem' }}>{error}</p>}
        {success && <p style={{ color: 'green', marginTop: '1rem' }}>{success}</p>}
      </form>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

